"use client";

import {
  Paperclip,
  Download,
  Calendar,
  CalendarCheck,
  Building2,
  Palette,
  CalendarPlus,
  FileCheck2,
  ListOrdered,
  CalendarClock,
  Hammer,
  History,
  ChevronDown,
  AlertTriangle,
} from "lucide-react";
import { useState, type ReactNode } from "react";
import type { DesignRequestProgress } from "@/lib/designRequestProgress";
import DesignRequestCountdownBadge from "./DesignRequestCountdownBadge";
import LinkifiedText from "@/components/ui/LinkifiedText";

/**
 * أعمدة صف عرض القائمة على سطح المكتب — تُصدَّر لأن رأس الجدول (في
 * DesignRequestsClient) يحتاج التوزيع نفسه بالحرف ليصطف مع كل صف.
 * لا تظهر إلا من lg فأعلى؛ الجوال يبقى على السطر المرن أدناه.
 */
export const DESIGN_REQUEST_LIST_GRID_COLS =
  "lg:grid-cols-[130px_minmax(0,2fr)_150px_96px_140px_64px_20px]";

export type DesignRequestCardData = {
  id: string;
  title: string;
  description: string | null;
  /** Pre-formatted on the server (Intl + civil-date anchoring) — never format dates in this component. */
  submittedAt: string;
  scheduledStartDate: string;
  expectedCompletionDate: string;
  /** When it was actually finalised — charity sign-off or the 24h auto-approval. */
  completedAt?: string | null;
  /**
   * Free-text note staff left on the current hand-off — the first delivery
   * (while AWAITING_REVIEW) or the final one (once COMPLETED). A later
   * delivery replaces the earlier note; the full history is in the log.
   */
  completionNote?: string | null;
  /// أُغلق بملاحظات زاد دون تنفيذ تعديلات الجمعية — نهاية أخرى غير التسليم.
  closedWithNotes?: boolean | null;
  /** When it was rejected. */
  rejectedAt?: string | null;
  /** Finalised by the deadline passing rather than by the charity acting. */
  autoApproved?: boolean;
  /** When a designer picked it up. Null means it is still only queued. */
  startedAt?: string | null;
  /** Who picked it up — shown so nobody has to ask. */
  startedByName?: string | null;
  /** 1-based place in this charity's execution queue, when it is queued. */
  queuePosition?: number | null;
  queueTotal?: number | null;
  /**
   * Whether this request went through the charity review cycle at all.
   *
   * Requests completed before that cycle existed were finished by Zad
   * directly, and nothing records who signed them off — so they show the
   * date alone rather than claiming an approval that never happened.
   */
  wasReviewed?: boolean;
  status?: string;
  /** Staff view only. */
  charityName?: string;
  /** Chosen design types, for display. */
  types?: { id: string; name: string }[];
  /** Business days promised: the types' total plus anything staff added. */
  totalWorkingDays?: number;
  addedDays?: number;
  /** Why the deadline moved. Shown to the charity, newest last. */
  extensions?: { id: string; days: number; reason: string; createdAt: string }[];
  attachments: { id: string; fileUrl: string; fileName: string; fileSize: number | null }[];
  /** Finished files from Zad, attached on delivery. Kept after completion. */
  deliverables?: { id: string; fileUrl: string; fileName: string; fileSize: number | null }[];
};

export default function DesignRequestCard({
  request,
  progress,
  actions,
  footer,
  onOpenLog,
  variant = "card",
}: {
  request: DesignRequestCardData;
  progress: DesignRequestProgress;
  actions?: ReactNode;
  /**
   * Opens this request's history. Given to both dashboards, because the
   * charity has the same right to know who moved its delivery date.
   */
  onOpenLog?: () => void;
  /**
   * Rendered below the status actions and separated from them.
   *
   * For things that apply whatever state the request is in — deleting it,
   * today — so they do not have to be repeated inside every status branch,
   * which is how the delete button ended up available on one tab only.
   */
  footer?: ReactNode;
  /**
   * "card" (default, unchanged) sits in a grid and stretches to match its row.
   * "list" collapses each request to a single line — badge, charity, title —
   * that expands in place to the full detail (same content as "card") when
   * clicked. Opt-in only: the charity portal renders this same component and
   * must keep getting exactly the "card" markup it always has.
   */
  variant?: "card" | "list";
}) {
  const [expanded, setExpanded] = useState(false);
  const isList = variant === "list";
  // Only meaningful in list mode — a card is always "open". Resets to closed
  // whenever the underlying request changes identity (key changes on the
  // component), which is what keeps a freshly-completed request from staying
  // expanded when it re-sorts into a different tab.
  const [rowOpen, setRowOpen] = useState(false);
  const isCollapsedRow = isList && !rowOpen;

  // A rough threshold rather than measuring the rendered box: the clamp is two
  // lines, and anything under this reliably fits in them at every card width.
  const isLongDescription = (request.description?.length ?? 0) > 110;

  if (isCollapsedRow) {
    const typesLabel = request.types && request.types.length > 0 ? request.types.map((t) => t.name).join("، ") : "—";
    const chevron = (
      <ChevronDown className="w-4 h-4 text-slate-300 dark:text-slate-600 shrink-0 -rotate-90 group-hover:text-primary dark:group-hover:text-teal-400 transition-colors" />
    );

    return (
      <button
        type="button"
        onClick={() => setRowOpen(true)}
        className="design-requests-ui group w-full rounded-2xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-[#0A0A0A] shadow-sm hover:shadow-md dark:shadow-none hover:border-primary/40 dark:hover:border-teal-500/40 transition-all duration-300 text-right cursor-pointer"
      >
        {/* صف الجدول — سطح المكتب. كل معلومة في عمودها الثابت، ورأس الجدول في
            DesignRequestsClient يطابقها بالحرف. */}
        <div className={`hidden lg:grid ${DESIGN_REQUEST_LIST_GRID_COLS} items-center gap-3 px-4 py-2.5`}>
          <span
            title={request.charityName}
            className="min-w-0 truncate flex items-center gap-1 text-primary dark:text-teal-300 font-bold"
            style={{ fontSize: "var(--dr-fs-eyebrow)" }}
          >
            {request.charityName && <Building2 className="w-3 h-3 shrink-0" />}
            {request.charityName || "—"}
          </span>

          <span
            title={request.title}
            className="min-w-0 truncate font-bold text-slate-900 dark:text-slate-100"
            style={{ fontSize: "var(--dr-fs-title)" }}
          >
            {request.title}
          </span>

          <span
            title={typesLabel}
            className="min-w-0 truncate text-slate-500 dark:text-slate-400"
            style={{ fontSize: "var(--dr-fs-meta)" }}
          >
            {typesLabel}
          </span>

          <span className="text-slate-400 dark:text-slate-500 tabular-nums" style={{ fontSize: "var(--dr-fs-meta)" }}>
            {request.submittedAt}
          </span>

          <div className="w-fit">
            <DesignRequestCountdownBadge progress={progress} />
          </div>

          {request.attachments.length > 0 ? (
            <span
              className="flex items-center gap-1 text-slate-400 dark:text-slate-500"
              style={{ fontSize: "var(--dr-fs-eyebrow)" }}
              title={`${request.attachments.length} مرفق`}
            >
              <Paperclip className="w-3 h-3" />
              {request.attachments.length}
            </span>
          ) : <span className="text-slate-300 dark:text-slate-600">—</span>}

          {chevron}
        </div>

        {/* سطر الجوال — دون lg. مضغوط ومرن كما كان. */}
        <div className="lg:hidden flex items-center gap-2.5 px-4 py-2.5">
          {chevron}
          {request.charityName && (
            <span
              className="hidden sm:flex items-center gap-1 text-primary dark:text-teal-300 font-bold shrink-0"
              style={{ fontSize: "var(--dr-fs-eyebrow)" }}
            >
              <Building2 className="w-3 h-3" />
              {request.charityName}
            </span>
          )}
          <span
            className="flex-1 min-w-0 truncate font-bold text-slate-900 dark:text-slate-100"
            style={{ fontSize: "var(--dr-fs-title)" }}
          >
            {request.title}
          </span>
          {/* الأيام المتبقية مع المرفقات معاً على الطرف الآخر من العنوان، لا
              مزدحمة مع الجمعية والعنوان على نفس الجانب. */}
          <DesignRequestCountdownBadge progress={progress} />
          {request.attachments.length > 0 && (
            <span
              className="hidden sm:flex items-center gap-1 text-slate-400 dark:text-slate-500 shrink-0"
              style={{ fontSize: "var(--dr-fs-eyebrow)" }}
              title={`${request.attachments.length} مرفق`}
            >
              <Paperclip className="w-3 h-3" />
              {request.attachments.length}
            </span>
          )}
        </div>
      </button>
    );
  }

  return (
    <div
      className={`design-requests-ui group flex flex-col rounded-2xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-[#0A0A0A] shadow-sm hover:shadow-md dark:shadow-none hover:border-primary/40 dark:hover:border-teal-500/40 transition-all duration-300 ${
        isList ? "p-4" : "h-full p-5"
      }`}
    >
      {isList && (
        <button
          type="button"
          onClick={() => setRowOpen(false)}
          className="flex items-center gap-1.5 mb-2 text-slate-400 hover:text-primary dark:text-slate-500 dark:hover:text-teal-400 font-bold transition-colors cursor-pointer"
          style={{ fontSize: "var(--dr-fs-eyebrow)" }}
        >
          <ChevronDown className="w-3.5 h-3.5" />
          طيّ
        </button>
      )}
      <div className="flex items-start justify-between gap-4">
        <div className="min-w-0 flex-1 space-y-1">
          {request.charityName && (
            <div
              className="flex items-center gap-1.5 text-primary dark:text-teal-300 font-bold"
              style={{ fontSize: "var(--dr-fs-eyebrow)" }}
            >
              <Building2 className="w-3 h-3" />
              <span>{request.charityName}</span>
            </div>
          )}
          {/* Wraps rather than truncating: the title is what identifies the
              request, and a cut one leaves two designs for the same charity
              looking identical. The card grows instead — the grid stretches
              its row to match, so the cards beside it stay aligned. */}
          <div className="flex items-start gap-2">
            <h3
              className="font-bold text-slate-900 dark:text-slate-100 break-words leading-snug min-w-0 flex-1"
              style={{ fontSize: "var(--dr-fs-title)", textWrap: "balance" }}
            >
              {request.title}
            </h3>
            {onOpenLog && (
              <button
                type="button"
                onClick={onOpenLog}
                title="سجل الطلب"
                aria-label="سجل الطلب"
                className="shrink-0 mt-0.5 p-1 rounded-md text-slate-300 hover:text-primary dark:text-slate-600 dark:hover:text-teal-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
              >
                <History className="w-3.5 h-3.5" />
              </button>
            )}
          </div>
          {request.description && (
            <div>
              <p
                className={`text-slate-500 dark:text-slate-400 whitespace-pre-line ${
                  expanded ? "" : "line-clamp-2"
                }`}
                style={{ fontSize: "var(--dr-fs-body)" }}
              >
                {/* A brief often IS a link — a reference, a folder, a previous
                    design — and pasting it as dead text means retyping it into
                    the address bar by hand. */}
                <LinkifiedText text={request.description} />
              </p>
              {/* Only offered when the text is actually long enough to be cut.
                  A "show more" that reveals nothing is worse than none. */}
              {isLongDescription && (
                <button
                  type="button"
                  onClick={() => setExpanded((v) => !v)}
                  className="mt-1 font-bold text-primary dark:text-teal-300 hover:underline"
                  style={{ fontSize: "var(--dr-fs-eyebrow)" }}
                >
                  {expanded ? "عرض أقل" : "عرض المزيد"}
                </button>
              )}
            </div>
          )}
        </div>
        <div className="shrink-0">
          <DesignRequestCountdownBadge progress={progress} />
        </div>
      </div>

      {request.types && request.types.length > 0 && (
        <div className="mt-3 flex flex-wrap items-center gap-1.5">
          <Palette className="w-3 h-3 text-slate-400 dark:text-slate-500 shrink-0" />
          {request.types.map((t) => (
            <span
              key={t.id}
              className="px-2 py-0.5 rounded-md bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300"
              style={{ fontSize: "var(--dr-fs-eyebrow)" }}
            >
              {t.name}
            </span>
          ))}
        </div>
      )}

      {request.extensions && request.extensions.length > 0 && (
        <div className="mt-3 rounded-xl bg-amber-500/[0.07] px-3 py-2.5 space-y-2">
          <p
            className="flex items-center gap-1.5 font-bold text-amber-700 dark:text-amber-400"
            style={{ fontSize: "var(--dr-fs-eyebrow)" }}
          >
            <CalendarPlus className="w-3 h-3 shrink-0" />
            تم تمديد موعد التسليم
          </p>
          {request.extensions.map((ext) => (
            <div key={ext.id} className="flex items-start gap-2">
              <span
                className="shrink-0 px-1.5 py-0.5 rounded bg-amber-500/15 text-amber-700 dark:text-amber-400 font-bold tabular-nums"
                style={{ fontSize: "var(--dr-fs-eyebrow)" }}
              >
                +{ext.days}
              </span>
              <span
                className="text-slate-600 dark:text-slate-300 whitespace-pre-line"
                style={{ fontSize: "var(--dr-fs-eyebrow)" }}
              >
                {ext.reason}
                <span className="text-slate-400 dark:text-slate-500"> — {ext.createdAt}</span>
              </span>
            </div>
          ))}
        </div>
      )}

      <div className={`flex flex-col ${isList ? "pt-3 gap-3" : "mt-auto pt-6 gap-4"}`}>
        <div
          className={`text-slate-500 dark:text-slate-400 ${isList ? "flex flex-wrap gap-x-4 gap-y-1.5" : "flex flex-col gap-2"}`}
          style={{ fontSize: "var(--dr-fs-meta)" }}
        >
          <span className="flex items-center gap-2">
            <Calendar className="w-4 h-4 text-slate-400 dark:text-slate-500 shrink-0" />
            <span>الرفع:</span> <span className="font-bold text-slate-700 dark:text-slate-200">{request.submittedAt}</span>
          </span>

          {/* When the work is due to START.

              The card carried this date all along and never showed it, so it
              could say when a design was requested and when it lands but not
              when anyone picks it up — which is the question a charity waiting
              in a queue actually asks. Dropped once work has begun: a planned
              start is only news until it happens. */}
          {request.status === "PENDING" && !request.startedAt && (
            <span className="flex items-center gap-2">
              <CalendarClock className="w-4 h-4 text-slate-400 dark:text-slate-500 shrink-0" />
              <span>بدء التنفيذ:</span>{" "}
              <span className="font-bold text-slate-700 dark:text-slate-200">
                {request.scheduledStartDate}
              </span>
            </span>
          )}
          {request.status === "COMPLETED" ? (
            <span className="flex items-center gap-2">
              <CalendarCheck className="w-4 h-4 text-emerald-600 dark:text-emerald-400 shrink-0" />
              <span className="text-emerald-700 dark:text-emerald-400">تاريخ الإنجاز:</span>{" "}
              <span className="font-bold text-slate-900 dark:text-slate-100">
                {request.completedAt ?? "—"}
              </span>
              {request.wasReviewed && (
                <span className="text-slate-400 dark:text-slate-500">
                  ({request.autoApproved ? "اعتماد تلقائي — لم تردّ الجمعية" : "باعتماد الجمعية"})
                </span>
              )}
            </span>
          ) : request.status === "REJECTED" ? (
            <span className="flex items-center gap-2">
              <CalendarCheck className="w-4 h-4 text-rose-500 shrink-0" />
              <span className="text-rose-600 dark:text-rose-400">تاريخ الإعادة:</span>{" "}
              <span className="font-bold text-slate-900 dark:text-slate-100">
                {request.rejectedAt ?? "—"}
              </span>
            </span>
          ) : (
            <span className="flex items-center gap-2">
              <CalendarCheck className="w-4 h-4 text-primary dark:text-teal-400 shrink-0" />
              <span className="text-primary dark:text-teal-400">وقت التسليم:</span>{" "}
              <span className="font-bold text-slate-900 dark:text-slate-100">{request.expectedCompletionDate}</span>
              {typeof request.totalWorkingDays === "number" && (
                <span className="text-slate-400 dark:text-slate-500 tabular-nums">
                  ({request.totalWorkingDays} يوم عمل
                  {request.addedDays ? ` منها ${request.addedDays} مضافة` : ""})
                </span>
              )}
            </span>
          )}

          {/* Staff's note on the current hand-off. Shown while the request is
              still with the charity for review, and again once closed — a later
              delivery replaces the note, same as it replaces the files. */}
          {request.status === "COMPLETED" &&
            request.completionNote &&
            (request.closedWithNotes ? (
              // A request that ended without the change being made. Saying
              // "ملاحظة التسليم" here would describe a delivery that never
              // happened, which is the one thing the charity must not be told.
              <span className="flex items-start gap-2">
                <AlertTriangle className="w-4 h-4 text-rose-500 shrink-0 mt-0.5" />
                <span className="leading-relaxed">
                  <span className="text-rose-600 dark:text-rose-400 font-bold">
                    أُغلق الطلب بملاحظات فريق زاد:{" "}
                  </span>
                  <LinkifiedText text={request.completionNote} className="whitespace-pre-line" />
                </span>
              </span>
            ) : (
              <span className="flex items-start gap-2">
                <FileCheck2 className="w-4 h-4 text-slate-400 shrink-0 mt-0.5" />
                <span className="leading-relaxed">
                  <span className="text-slate-600 dark:text-slate-300 font-bold">ملاحظة التسليم: </span>
                  <LinkifiedText text={request.completionNote} className="whitespace-pre-line" />
                </span>
              </span>
            ))}

          {/* Where it sits in the queue. Only while it is still waiting —
              once a designer has it, the position is no longer the answer to
              "when does mine get done". */}
          {request.status === "PENDING" && !request.startedAt && request.queuePosition ? (
            <span className="flex items-center gap-2">
              <ListOrdered className="w-4 h-4 text-slate-400 shrink-0" />
              <span className="text-slate-500 dark:text-slate-400">الترتيب في التنفيذ:</span>{" "}
              <span className="font-bold text-slate-900 dark:text-slate-100 tabular-nums">
                {request.queuePosition}
                {request.queueTotal ? ` من ${request.queueTotal}` : ""}
              </span>
            </span>
          ) : null}
        </div>

        {/* Work has begun. The fact alone, and what to do about it.

            Deliberately without the timestamp or the designer's name: the
            reader's question here is "can I still change this", not "who has
            it and since when". Both are recorded and both are in the request
            log, one click away, for anyone who does want to know. */}
        {request.startedAt && request.status === "PENDING" && (
          <div
            className="mt-3 px-3 py-2.5 rounded-xl bg-indigo-500/[0.07] text-indigo-700 dark:text-indigo-300 leading-relaxed"
            style={{ fontSize: "var(--dr-fs-meta)" }}
          >
            <span className="inline-flex items-center gap-1.5 font-bold">
              <Hammer className="w-3.5 h-3.5 shrink-0" />
              جاري العمل على الطلب
            </span>
            <span className="text-indigo-600/80 dark:text-indigo-300/80">
              {" "}— في حال هناك ملاحظات وتعديلات على الطلب يرجى التواصل مع المسؤول
              من شركة زاد.
            </span>
          </div>
        )}

        {request.attachments.length > 0 && (
          <div className="flex flex-wrap gap-2 pt-4 border-t border-slate-100 dark:border-slate-800/60">
            {request.attachments.map((att) => (
              <a
                key={att.id}
                href={att.fileUrl}
                target="_blank"
                rel="noreferrer"
                className="flex items-center gap-2 px-3 py-1.5 rounded-lg border border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-[#111] hover:border-primary/30 hover:bg-primary/[0.04] dark:hover:bg-primary/10 transition-colors"
                style={{ fontSize: "var(--dr-fs-meta)" }}
              >
                <Paperclip className="w-3.5 h-3.5 text-slate-400 dark:text-slate-500 shrink-0" />
                <span className="font-bold text-slate-700 dark:text-slate-300 truncate max-w-[140px]">
                  {att.fileName}
                </span>
              </a>
            ))}
          </div>
        )}

        {/* The delivered files, set apart from the brief: after completion this
            is the only attachment block left, and it is what the charity came
            back for. */}
        {request.deliverables && request.deliverables.length > 0 && (
          <div className="pt-4 border-t border-slate-100 dark:border-slate-800/60 space-y-2">
            <p
              className="flex items-center gap-1.5 font-bold text-primary dark:text-teal-300"
              style={{ fontSize: "var(--dr-fs-eyebrow)" }}
            >
              <FileCheck2 className="w-3.5 h-3.5 shrink-0" />
              الملفات النهائية
            </p>
            <div className="flex flex-wrap gap-2">
              {request.deliverables.map((att) => (
                <a
                  key={att.id}
                  href={att.fileUrl}
                  target="_blank"
                  rel="noreferrer"
                  className="flex items-center gap-2 px-3 py-1.5 rounded-lg border border-primary/30 bg-primary/[0.05] dark:bg-primary/10 hover:bg-primary/[0.1] transition-colors"
                  style={{ fontSize: "var(--dr-fs-meta)" }}
                >
                  <Download className="w-3.5 h-3.5 text-primary dark:text-teal-300 shrink-0" />
                  <span className="font-bold text-primary dark:text-teal-300 truncate max-w-[140px]">
                    {att.fileName}
                  </span>
                </a>
              ))}
            </div>
          </div>
        )}

        {actions && (
          <div className="pt-4 border-t border-slate-100 dark:border-slate-800/60 flex items-center justify-end gap-2">
            {actions}
          </div>
        )}

        {footer && <div className={actions ? "" : "pt-4 border-t border-slate-100 dark:border-slate-800/60"}>{footer}</div>}
      </div>
    </div>
  );
}
